<main class="section narrow"><a class="back" href="/admin/angebote">← Angebote</a><span class="eyebrow">Angebotsverwaltung</span><h1><?= $offer?'Angebot bearbeiten':'Neues Angebot' ?></h1><?php if($offer):?><div class="notice">Beim Speichern entsteht automatisch eine neue Angebotsversion. Bereits angenommene Aufträge behalten ihren damaligen Snapshot.</div><?php endif;?><form method="post" class="card admin-form form-grid"><?=App\Core\Csrf::field()?><label class="full">Titel<input name="title" value="<?=App\Core\View::e($offer['title']??'')?>" required></label><label>Kategorie<select name="category_id" required><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=((string)($offer['category_id']??'')===(string)$c['id'])?'selected':''?>><?=App\Core\View::e($c['name'])?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="draft" <?=($offer['status']??'')==='draft'?'selected':''?>>Entwurf</option><option value="active" <?=($offer['status']??'')==='active'?'selected':''?>>Aktiv</option><option value="disabled" <?=($offer['status']??'')==='disabled'?'selected':''?>>Deaktiviert</option></select></label><label class="full">Beschreibung<textarea name="description" rows="8" required><?=App\Core\View::e($version['description']??'')?></textarea></label><label>Vergütung (€)<input name="compensation" type="number" step="0.01" min="0" value="<?=App\Core\View::e($version['compensation']??'')?>" required></label><label>Erfüllungsmodell<select name="fulfillment_model"><option value="days">X Tage</option><option value="units">X Einheiten</option><option value="once">Einmalig</option><option value="digital">Digital</option><option value="combined">Kombination</option></select></label><label>Dauer / Anzahl<input name="duration_value" type="number" min="1" value="<?=App\Core\View::e($version['duration_value']??'')?>"></label><label>Einheit<input name="duration_unit" value="<?=App\Core\View::e($version['duration_unit']??'Tage')?>"></label><label class="check full"><input type="checkbox" name="is_private" value="1" <?=!empty($offer['is_private'])?'checked':''?>> Individuelles Privatangebot</label><label>Verkäuferin-ID<input name="seller_id" type="number" min="1" value="<?=App\Core\View::e($offer['seller_id']??'')?>"></label><label>Annahmefrist<input name="acceptance_deadline" type="datetime-local" value="<?=!empty($offer['acceptance_deadline'])?date('Y-m-d\TH:i',strtotime($offer['acceptance_deadline'])):''?>"></label><?php $jsonFields=['rules_json'=>'Regeln','evidence_json'=>'Nachweise','start_control_json'=>'Startkontrolle','shipping_json'=>'Versand','end_workflow_json'=>'Endworkflow','violation_json'=>'Verstoßlogik','settings_json'=>'Weitere Einstellungen'];foreach($jsonFields as $key=>$label):?><label class="full"><?=$label?> (JSON)<textarea name="<?=$key?>" rows="5"><?=App\Core\View::e(isset($version[$key])?json_encode(json_decode($version[$key],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE):'{}')?></textarea></label><?php endforeach;?><button class="btn primary full"><?=$offer?'Neue Version speichern':'Angebot anlegen'?></button></form></main>